var lv = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().Select(l=>l.Id).ToList();
Func<BuiltInCategory,int> cnt = c => new FilteredElementCollector(doc).OfCategory(c).WhereElementIsNotElementType().GetElementCount();
var wallTypes = new FilteredElementCollector(doc).OfClass(typeof(WallType)).Cast<WallType>().Select(w=>new{w.Name, kind=w.Kind.ToString(), wmm=Math.Round(w.Width*304.8)}).ToList();
var doors = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Doors).WhereElementIsElementType().Cast<FamilySymbol>().Select(s=>s.FamilyName+" : "+s.Name).ToList();
var wins = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Windows).WhereElementIsElementType().Cast<FamilySymbol>().Select(s=>s.FamilyName+" : "+s.Name).ToList();
var byLevel = new FilteredElementCollector(doc).WhereElementIsNotElementType().Where(e=>e.LevelId!=null && e.LevelId!=ElementId.InvalidElementId && e.Category!=null).GroupBy(e=>doc.GetElement(e.LevelId).Name+" | "+e.Category.Name).Select(g=>new{k=g.Key,n=g.Count()}).ToList();
var imports = new FilteredElementCollector(doc).OfClass(typeof(ImportInstance)).Count();
return new{walls=cnt(BuiltInCategory.OST_Walls),rooms=cnt(BuiltInCategory.OST_Rooms),floors=cnt(BuiltInCategory.OST_Floors),wallTypes,doors,wins,byLevel,imports};
